// seek_test: standalone smoke test for VideoSource::seekToFrame(), the
// single highest-risk item identified in the Dirk feasibility study
// (section 7). Exercises it against a synthetic clip rather than real
// (copyrighted) Dragon's Lair footage, which we don't have -- only its
// frame index (Lair.mp4.index) was ever provided.
//
// The test clip (assets/test_pattern.mp4, generated by
// tools/gen_test_pattern.sh) is a lossless yuv420p H.264 encode where every
// pixel of the Y (luma) plane is set to (frame_number mod 256) via ffmpeg's
// geq filter, operating directly in the YUV420P domain so there is no lossy
// RGB<->YUV round trip anywhere between generation and decode.
//
// Each check is therefore two independent signals at once:
//   1. currentFrameNumber() == requested frame -- validates VideoSource's
//      own PTS -> frame-number bookkeeping and keyframe/seek logic.
//   2. the decoded pixel content matches the *requested* frame number --
//      validates that the picture actually decoded is the right one, not
//      just that the bookkeeping says so (catches a self-consistent but
//      wrong seek, which check 1 alone could not).

#include "video/VideoSource.h"

extern "C" {
#include <libavutil/frame.h>
}

// This tool never touches SDL itself -- it only needs VideoSource/ffmpeg --
// but dirk_core links SDL2 PUBLIC (LaunchSettings/Bezel/InputMap all use
// it), so anything linking dirk_core inherits that dependency, SDL2main.a
// included on Windows. SDL2main.a expects to call a symbol named SDL_main,
// which only exists if some translation unit in the final link included
// <SDL.h> (its SDL_main.h header #define's main to SDL_main on Windows/iOS
// specifically) -- without it, the linker sees this file's own `main`
// under its real name and SDL2main.a's reference to SDL_main goes
// unresolved: "undefined reference to `SDL_main'". Including it here is a
// no-op on Linux (the rename is guarded to Windows/iOS inside SDL itself)
// and doesn't require actually calling any SDL API.
#include <SDL3/SDL.h>

#include <cstdio>
#include <cstdint>
#include <vector>

namespace {

bool checkFrame(dirk::VideoSource& disc, int64_t requested) {
    if (!disc.seekToFrame(requested)) {
        std::fprintf(stderr, "FAIL seekToFrame(%lld): returned false\n", static_cast<long long>(requested));
        return false;
    }
    int64_t got = disc.currentFrameNumber();
    if (got != requested) {
        std::fprintf(stderr, "FAIL seekToFrame(%lld): currentFrameNumber() = %lld\n",
                     static_cast<long long>(requested), static_cast<long long>(got));
        return false;
    }
    const AVFrame* pic = disc.currentPicture();
    if (!pic || !pic->data[0]) {
        std::fprintf(stderr, "FAIL seekToFrame(%lld): no decoded picture\n", static_cast<long long>(requested));
        return false;
    }
    uint8_t expected = static_cast<uint8_t>(requested % 256);
    uint8_t actual = pic->data[0][0];
    if (actual != expected) {
        std::fprintf(stderr, "FAIL seekToFrame(%lld): Y[0,0] = %d, expected %d\n",
                     static_cast<long long>(requested), actual, expected);
        return false;
    }
    std::fprintf(stderr, "PASS seekToFrame(%lld)\n", static_cast<long long>(requested));
    return true;
}

} // namespace

int main(int argc, char** argv) {
    if (argc < 2) {
        std::fprintf(stderr, "usage: %s <test_pattern.mp4>\n", argv[0]);
        return 1;
    }

    dirk::VideoSource disc;
    if (!disc.open(argv[1])) {
        std::fprintf(stderr, "FAIL: could not open %s\n", argv[1]);
        return 1;
    }

    int64_t last = disc.frameCount() - 1;
    if (last < 1) {
        std::fprintf(stderr, "FAIL: test clip has only %lld frame(s), need more\n",
                     static_cast<long long>(disc.frameCount()));
        return 1;
    }
    std::fprintf(stderr, "[seek_test] %s: %lld frames indexed\n", argv[1],
                 static_cast<long long>(disc.frameCount()));

    // Forward-decode, backward jump, re-visit, boundaries -- deliberately
    // out of monotonic order to exercise both "no seek needed, just decode
    // forward" and "seek back to a keyframe" code paths.
    std::vector<int64_t> plan = {
        0, 1, 2, 10,
        last / 2,
        last,
        0,               // jump straight back to the start
        last / 4,
        last / 2,        // revisit the same frame twice
        last - 1,
        3,
        last,
    };

    bool allPass = true;
    for (int64_t f : plan) {
        if (f < 0 || f > last) continue;
        if (!checkFrame(disc, f)) allPass = false;
    }

    std::fprintf(stderr, allPass ? "[seek_test] ALL PASS\n" : "[seek_test] SOME FAILED\n");
    return allPass ? 0 : 1;
}
